const raw = $json.stdout || "";

// Clean logs safely
let clean = raw.includes("logs returned.")
  ? raw.split("logs returned.").pop()
  : raw;

clean = clean || "";

const lines = clean.split("\n");

// Destination/platform mapping
const destinationMap = {
   // Twitter / X specific CDN ranges seen in your test
  "162.159.140": "X / Twitter CDN",
  "162.159.141": "X / Twitter CDN",

  // Facebook / Meta
  "31.13": "Facebook / Meta",
  "157.240": "Facebook / Instagram / WhatsApp / Meta",
  "69.171": "Facebook / Meta",
  "173.252": "Facebook / Meta",

  // Google / YouTube
  "142.250": "Google / YouTube",
  "172.217": "Google / YouTube",
  "216.58": "Google / YouTube",
  "74.125": "Google / YouTube",
  "8.8.8.8": "Google DNS",

  // Twitter / X
  "104.244": "Twitter / X",
  "199.16": "Twitter / X",
  "199.59": "Twitter / X",

  // TikTok / CDN
  "172.66": "TikTok / CDN",

  // Cloudflare / CDN fallback
  "162.159": "Cloudflare CDN",
  "104.16": "Cloudflare CDN",
  "104.17": "Cloudflare CDN",
  "104.18": "Cloudflare CDN",
  "104.21": "Cloudflare CDN",
  "172.67": "Cloudflare CDN"
};

// Source subnet to department/VLAN mapping
const departmentMap = [
  { prefix: "192.168.10.", department: "HR", vlan: "VLAN 10" },
  { prefix: "192.168.20.", department: "FINANCE", vlan: "VLAN 20" },
  { prefix: "192.168.30.", department: "IT", vlan: "VLAN 30" },
  { prefix: "192.168.40.", department: "STAFF", vlan: "VLAN 40" },
  { prefix: "192.168.50.", department: "SERVERS", vlan: "VLAN 50" },
  { prefix: "192.168.60.", department: "MGMT_INTERNAL", vlan: "VLAN 60" },
  { prefix: "192.168.70.", department: "GUEST", vlan: "VLAN 70" },
  { prefix: "192.168.99.", department: "MGMT", vlan: "VLAN 99" },
  { prefix: "192.168.120.", department: "HR_USERS", vlan: "VLAN 120" }
];

function getDepartmentInfo(srcIp) {
  const match = departmentMap.find(item => srcIp.startsWith(item.prefix));

  if (!match) {
    return {
      department: "UNKNOWN",
      vlan: "UNKNOWN"
    };
  }

  return {
    department: match.department,
    vlan: match.vlan
  };
}

function getDestinationName(dstIp, line = "") {
  const lowerLine = line.toLowerCase();

  // Prefer explicit FortiGate object/site/policy text if present
  if (lowerLine.includes("facebook.com") || lowerLine.includes("block_facebook")) {
    return "Facebook";
  }

  if (lowerLine.includes("instagram.com") || lowerLine.includes("block_instagram")) {
    return "Instagram";
  }

  if (lowerLine.includes("whatsapp.com") || lowerLine.includes("block_whatsapp")) {
    return "WhatsApp";
  }

  if (lowerLine.includes("youtube.com") || lowerLine.includes("block_youtube")) {
    return "YouTube";
  }

  if (lowerLine.includes("twitter.com") || lowerLine.includes("block_twitter")) {
    return "Twitter";
  }

  if (lowerLine.includes("x.com") || lowerLine.includes("block_x")) {
    return "X";
  }

  // Fallback to IP prefix mapping
  for (const prefix of Object.keys(destinationMap)) {
    if (dstIp.startsWith(prefix)) {
      return destinationMap[prefix];
    }
  }

  return dstIp;
}

const seen = new Set();
const results = [];

for (let line of lines) {
  if (line.includes('action="deny"') && line.includes("srcip=")) {
    const srcMatch = line.match(/srcip=([\d.]+)/);
    const dstMatch = line.match(/dstip=([\d.]+)/);

    const src = srcMatch ? srcMatch[1] : null;
    const dst = dstMatch ? dstMatch[1] : null;

    if (!src || !dst) continue;

    const key = `${src}-${dst}`;
    if (seen.has(key)) continue;
    seen.add(key);

    const deptInfo = getDepartmentInfo(src);
    const platform = getDestinationName(dst, line);

    results.push({
      user: `${src} (${deptInfo.department} - ${deptInfo.vlan})`,
      source_ip: src,
      department: deptInfo.department,
      vlan: deptInfo.vlan,
      destination: platform,
      raw_ip: dst,
      status: "DENIED"
    });
  }
}

// Clean Telegram-ready message
const message =
  results.length === 0
    ? "✅ No denied firewall logs found."
    : `🔥 FortiGate Denied Traffic Report

Total denied events: ${results.length}

${results
  .map((log, index) => {
    return `#${index + 1}
User: ${log.user}
Destination: ${log.destination}
Raw IP: ${log.raw_ip}
Status: ${log.status}`;
  })
  .join("\n\n")}`;

return {
  json: {
    logs: results,
    clean_message: message
  }
};
